use vstd::prelude::*;

verus! {
    // Compute element‐wise bitwise OR of two byte‐arrays of equal length.
    // We use Vec<u8> in the implementation and reason about its
    // mathematical model Vec@ (a sequence) in the specs.
    fn bitwise_or(a: Vec<u8>, b: Vec<u8>) -> (result: Vec<u8>)
        requires
            // The two inputs must have the same length
            a.len() == b.len(),
        ensures
            // The result has the same length
            result.len() == a.len(),
            // And each position i satisfies result[i] == a[i] | b[i]
            forall |i: usize|
                i < a.len() ==> result@[i] == a@[i] | b@[i],
    {
        let mut result: Vec<u8> = Vec::new();
        let n = a.len();
        let mut i: usize = 0;
        // We build result incrementally:
        // ‐ at each step i, result.len() == i
        // ‐ for all j<i, result[j] == a[j] | b[j]
        while i < n
            invariant
                i <= n,
                result.len() == i,
                forall |j: usize|
                    j < i ==> result@[j] == a@[j] | b@[j],
            decreases
                // remaining iterations
                (n - i) as nat,
        {
            // read the two bytes at position i
            let ai: u8 = a[i];
            let bi: u8 = b[i];
            // compute their bitwise OR
            let or_val: u8 = ai | bi;
            // append to result
            result.push(or_val);
            // advance
            i += 1;
        }
        result
    }
}

